import{_ as a,c as e,o as i,a0 as o}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Introducción al juego mental - Diapositivas para el facilitador","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/es/facilitator-slides.md","filePath":"public/downloads/es/facilitator-slides.md"}');const r=a({name:"public/downloads/es/facilitator-slides.md"},[["render",function(a,t,r,n,s,l){return i(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="introduccion-al-juego-mental-diapositivas-para-el-facilitador" tabindex="-1">Introducción al juego mental - Diapositivas para el facilitador <a class="header-anchor" href="#introduccion-al-juego-mental-diapositivas-para-el-facilitador" aria-label="Permalink to &quot;Introducción al juego mental - Diapositivas para el facilitador&quot;">​</a></h1><p><strong>Academia de petanca</strong><em>Guía de sesión para facilitadores</em></p><hr><h2 id="diapositiva-1-bienvenida" tabindex="-1">Diapositiva 1: Bienvenida <a class="header-anchor" href="#diapositiva-1-bienvenida" aria-label="Permalink to &quot;Diapositiva 1: Bienvenida&quot;">​</a></h2><h1 id="introduccion-al-juego-mental" tabindex="-1">Introducción al juego mental <a class="header-anchor" href="#introduccion-al-juego-mental" aria-label="Permalink to &quot;Introducción al juego mental&quot;">​</a></h1><p><strong>Para jugadores de petanca de élite</strong></p><h3 id="hoy-descubriras" tabindex="-1">Hoy descubrirás: <a class="header-anchor" href="#hoy-descubriras" aria-label="Permalink to &quot;Hoy descubrirás:&quot;">​</a></h3><ul><li>🧠 Cómo crear las condiciones adecuadas para “la zona”</li><li>💪 Cómo silenciar a tu crítico interno</li><li>🎪 Herramientas prácticas que funcionan bajo presión</li></ul><p><strong>¡Prepárate para una sesión interactiva!</strong></p><hr><h2 id="diapositiva-2-encuesta-rapida-¡levanten-la-mano-🙋" tabindex="-1">Diapositiva 2: Encuesta rápida: ¡Levanten la mano! 🙋 <a class="header-anchor" href="#diapositiva-2-encuesta-rapida-¡levanten-la-mano-🙋" aria-label="Permalink to &quot;Diapositiva 2: Encuesta rápida: ¡Levanten la mano! 🙋&quot;">​</a></h2><h3 id="¿quien-ha-experimentado-esto" tabindex="-1">¿Quién ha experimentado esto? <a class="header-anchor" href="#¿quien-ha-experimentado-esto" aria-label="Permalink to &quot;¿Quién ha experimentado esto?&quot;">​</a></h3><p><strong>Levanta la mano si alguna vez:</strong></p><ol><li><p>Hiciste un tiro perfecto en la práctica... ¿y luego lo fallaste en la competencia? 🎯❌</p></li><li><p>¿Sentiste que tu mente se aceleraba cuando necesitabas mantener la calma? 🧠💨</p></li><li><p>¿Te criticaste a ti mismo después de un error? 😤</p></li><li><p>¿Tuviste un juego donde todo encajó a la perfección? ✨</p></li></ol><p>¡No estás solo! ¡Solucionémoslo juntos!</p><hr><h2 id="diapositiva-3-la-paradoja-del-jugador-de-elite" tabindex="-1">Diapositiva 3: La paradoja del jugador de élite <a class="header-anchor" href="#diapositiva-3-la-paradoja-del-jugador-de-elite" aria-label="Permalink to &quot;Diapositiva 3: La paradoja del jugador de élite&quot;">​</a></h2><h3 id="ya-tienes-las-habilidades-¿entonces-por-que" tabindex="-1">Ya tienes las habilidades... ¿entonces por qué? <a class="header-anchor" href="#ya-tienes-las-habilidades-¿entonces-por-que" aria-label="Permalink to &quot;Ya tienes las habilidades... ¿entonces por qué?&quot;">​</a></h3><p><strong>✅TIENES:</strong></p><ul><li>Excelente técnica (miles de horas)</li><li>Años de experiencia</li><li>Capacidad física</li></ul><p><strong>❌ Pero tienes dificultades con:</strong></p><ul><li>Acceder a esa técnica bajo presión</li><li>Mantenerse constante en la competición</li><li>Recuperarse después de los errores</li></ul><h3 id="¿la-pieza-que-falta-🧩" tabindex="-1">¿La pieza que falta? 🧩 <a class="header-anchor" href="#¿la-pieza-que-falta-🧩" aria-label="Permalink to &quot;¿La pieza que falta? 🧩&quot;">​</a></h3><p><strong>Tu juego mental.</strong></p><p><em>&quot;La diferencia entre el bien y la excelencia es lo que ocurre entre tus orejas.&quot;</em></p><hr><h2 id="diapositiva-4-la-zona-¡conoces-esta-sensacion-⚡" tabindex="-1">Diapositiva 4: La Zona - ¡Conoces esta sensación! ⚡ <a class="header-anchor" href="#diapositiva-4-la-zona-¡conoces-esta-sensacion-⚡" aria-label="Permalink to &quot;Diapositiva 4: La Zona - ¡Conoces esta sensación! ⚡&quot;">​</a></h2><h3 id="¿recuerdas-ese-juego-perfecto" tabindex="-1">¿Recuerdas ese juego perfecto? <a class="header-anchor" href="#¿recuerdas-ese-juego-perfecto" aria-label="Permalink to &quot;¿Recuerdas ese juego perfecto?&quot;">​</a></h3><p><strong>Todo se sintió:</strong></p><ul><li>⏱️ El tiempo se ralentizó</li><li>🎯 Sin esfuerzo y automático</li><li>🧘 Completamente concentrado</li><li>🎪 Como si no te lo pudieras perder</li></ul><h3 id="esa-es-quot-la-zona-quot-estado-de-flujo" tabindex="-1">Esa es &quot;La Zona&quot; (Estado de Flujo) <a class="header-anchor" href="#esa-es-quot-la-zona-quot-estado-de-flujo" aria-label="Permalink to &quot;Esa es &amp;quot;La Zona&amp;quot; (Estado de Flujo)&quot;">​</a></h3><p><strong>La Pregunta:</strong> ¿Cómo accedemos a él de manera consistente y no solo por accidente?</p><p><strong>La respuesta:</strong><em>Entendiendo tus dos modos de mente...</em></p><hr><h2 id="diapositiva-5-tu-cerebro-tiene-dos-modos-🧠" tabindex="-1">Diapositiva 5: Tu cerebro tiene dos modos 🧠 <a class="header-anchor" href="#diapositiva-5-tu-cerebro-tiene-dos-modos-🧠" aria-label="Permalink to &quot;Diapositiva 5: Tu cerebro tiene dos modos 🧠&quot;">​</a></h2><h3 id="🤔-modo-de-planificacion-cerebro-analitico" tabindex="-1">🤔 MODO DE PLANIFICACIÓN (Cerebro Analítico) <a class="header-anchor" href="#🤔-modo-de-planificacion-cerebro-analitico" aria-label="Permalink to &quot;🤔 MODO DE PLANIFICACIÓN (Cerebro Analítico)&quot;">​</a></h3><p><strong>Cuándo usar:</strong> ANTES de la inyección</p><ul><li>📊 Analizando el terreno</li><li>🎯 Elegir tu estrategia</li><li>⚖️ Sopesar los riesgos</li><li>🤝Decidiendo el tiro</li></ul><h3 id="modo-de-ejecucion-flow-brain" tabindex="-1">MODO DE EJECUCIÓN (Flow Brain) <a class="header-anchor" href="#modo-de-ejecucion-flow-brain" aria-label="Permalink to &quot;MODO DE EJECUCIÓN (Flow Brain)&quot;">​</a></h3><p><strong>Cuándo usarlo:</strong> DURANTE la toma</p><ul><li>💪 Confiando en tu cuerpo</li><li>🚫 NO pensar en la técnica</li><li>⏰ Solo el momento presente</li><li>🤖 Rendimiento automático</li></ul><h3 id="⚠️-el-problema" tabindex="-1">⚠️ EL PROBLEMA: <a class="header-anchor" href="#⚠️-el-problema" aria-label="Permalink to &quot;⚠️ EL PROBLEMA:&quot;">​</a></h3><p><strong>¡La mayoría de los jugadores permanecen en modo de planificación durante la ejecución!</strong><em>Tu cerebro analítico interfiere con tu desempeño automático.</em></p><hr><h2 id="diapositiva-6-el-interruptor-tu-arma-secreta-🔄" tabindex="-1">Diapositiva 6: El interruptor: tu arma secreta 🔄 <a class="header-anchor" href="#diapositiva-6-el-interruptor-tu-arma-secreta-🔄" aria-label="Permalink to &quot;Diapositiva 6: El interruptor: tu arma secreta 🔄&quot;">​</a></h2><h3 id="domina-esta-habilidad" tabindex="-1">Domina esta habilidad: <a class="header-anchor" href="#domina-esta-habilidad" aria-label="Permalink to &quot;Domina esta habilidad:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="el-proceso" tabindex="-1">El proceso: <a class="header-anchor" href="#el-proceso" aria-label="Permalink to &quot;El proceso:&quot;">​</a></h3><p><strong>1️⃣ ANTES (10-15 segundos):</strong></p><ul><li>🤔 Analiza todo</li><li>📊 Planifica tu estrategia</li><li>✅Toma tu decisión</li></ul><p><strong>2️⃣ EL INTERRUPTOR (3 respiraciones):</strong></p><ul><li>🌬️ Respira profundamente</li><li>🧘 Despeja tu mente</li><li>🔄Deja ir el análisis</li></ul><p><strong>3️⃣ DURANTE (2-3 segundos):</strong></p><ul><li>🎯Confía completamente</li><li>🤖 Déjalo pasar</li><li>⚡ Ejecutar automáticamente</li></ul><p><strong>¡Practica este cambio = flujo de acceso a pedido!</strong></p><hr><h2 id="diapositiva-7-actividad-¡pruebalo-ahora-🎯" tabindex="-1">Diapositiva 7: ACTIVIDAD - ¡Pruébalo ahora! 🎯 <a class="header-anchor" href="#diapositiva-7-actividad-¡pruebalo-ahora-🎯" aria-label="Permalink to &quot;Diapositiva 7: ACTIVIDAD - ¡Pruébalo ahora! 🎯&quot;">​</a></h2><h3 id="practiquemos-el-cambio-2-minutos" tabindex="-1">Practiquemos el cambio (2 minutos) <a class="header-anchor" href="#practiquemos-el-cambio-2-minutos" aria-label="Permalink to &quot;Practiquemos el cambio (2 minutos)&quot;">​</a></h3><p><strong>¡Todos de pie!</strong></p><ol><li><p><strong>Modo de planificación (10 segundos):</strong> Imagina analizar un tiro. Piensa en el terreno, la estrategia y los riesgos.</p></li><li><p><strong>El cambio (3 respiraciones):</strong> Respira profundamente tres veces. Despeja tu mente con cada exhalación.</p></li><li><p><strong>Modo de ejecución (3 segundos):</strong> Imagina lanzar. Sin pensar. Solo confía y fluye.</p></li></ol><p>¿Cómo te sentiste? ¿Diferente?</p><p><em>Siéntate y discutamos...</em></p><hr><h2 id="diapositiva-8-conoce-a-tu-critico-interno-😈" tabindex="-1">Diapositiva 8: Conoce a tu crítico interno 😈 <a class="header-anchor" href="#diapositiva-8-conoce-a-tu-critico-interno-😈" aria-label="Permalink to &quot;Diapositiva 8: Conoce a tu crítico interno 😈&quot;">​</a></h2><h3 id="¿te-suena-familiar-esta-voz" tabindex="-1">¿Te suena familiar esta voz? <a class="header-anchor" href="#¿te-suena-familiar-esta-voz" aria-label="Permalink to &quot;¿Te suena familiar esta voz?&quot;">​</a></h3><p><strong>Después de un mal tiro:</strong></p><ul><li>💢 &quot;¡Eso fue TERRIBLE!&quot;</li><li>😤 &quot;¡SIEMPRE cometes errores bajo presión!&quot;</li><li>😰 &quot;¡Todos te están viendo fracasar!&quot;</li><li>😞 &quot;¡No eres lo suficientemente bueno!&quot;</li></ul><h3 id="encuesta-rapida-🙋" tabindex="-1">Encuesta rápida: 🙋 <a class="header-anchor" href="#encuesta-rapida-🙋" aria-label="Permalink to &quot;Encuesta rápida: 🙋&quot;">​</a></h3><p><strong>¿Quién escucha esta voz regularmente?</strong></p><h3 id="la-verdad" tabindex="-1">La verdad: <a class="header-anchor" href="#la-verdad" aria-label="Permalink to &quot;La verdad:&quot;">​</a></h3><p><strong>Tu crítico interno está tratando de ayudarte...</strong><em>Pero en realidad está destruyendo tu rendimiento.</em></p><hr><h2 id="diapositiva-9-¡despide-a-tu-critico-y-contrata-a-tu-entrenador-🔄" tabindex="-1">Diapositiva 9: ¡Despide a tu crítico y contrata a tu entrenador! 🔄 <a class="header-anchor" href="#diapositiva-9-¡despide-a-tu-critico-y-contrata-a-tu-entrenador-🔄" aria-label="Permalink to &quot;Diapositiva 9: ¡Despide a tu crítico y contrata a tu entrenador! 🔄&quot;">​</a></h2><h3 id="la-transformacion" tabindex="-1">La transformación: <a class="header-anchor" href="#la-transformacion" aria-label="Permalink to &quot;La transformación:&quot;">​</a></h3><table tabindex="0"><thead><tr><th>😈 Crítico Interno</th><th>➡️</th><th>😊 Coach Interno</th></tr></thead><tbody><tr><td>&quot;¡SIEMPRE la cagas!&quot;</td><td>→</td><td>&quot;Ya he hecho esta toma 1000 veces&quot;</td></tr><tr><td>&quot;¡Eso fue TERRIBLE!&quot;</td><td>→</td><td>&quot;¿Qué puedo aprender de esto?&quot;</td></tr><tr><td>&quot;¡Todos te están juzgando!&quot;</td><td>→</td><td>&quot;Concéntrate en MI juego, no en sus opiniones&quot;</td></tr><tr><td>&quot;¡No eres lo suficientemente bueno!&quot;</td><td>→</td><td>&quot;Estoy mejorando cada día&quot;</td></tr></tbody></table><h3 id="el-impacto" tabindex="-1">El impacto: <a class="header-anchor" href="#el-impacto" aria-label="Permalink to &quot;El impacto:&quot;">​</a></h3><p><strong>Crítico = Ansiedad, tensión, bajo rendimiento</strong><strong>Coach = Confianza, relajación, máximo rendimiento</strong></p><hr><h2 id="diapositiva-10-actividad-¡replantea-tu-critica-💬" tabindex="-1">Diapositiva 10: ACTIVIDAD: ¡Replantea tu crítica! 💬 <a class="header-anchor" href="#diapositiva-10-actividad-¡replantea-tu-critica-💬" aria-label="Permalink to &quot;Diapositiva 10: ACTIVIDAD: ¡Replantea tu crítica! 💬&quot;">​</a></h2><h3 id="ejercicio-en-pareja-3-minutos" tabindex="-1">Ejercicio en pareja (3 minutos) <a class="header-anchor" href="#ejercicio-en-pareja-3-minutos" aria-label="Permalink to &quot;Ejercicio en pareja (3 minutos)&quot;">​</a></h3><p><strong>Gira hacia la persona que está a tu lado:</strong></p><p><strong>Persona A (1,5 min):</strong></p><ol><li>Comparte una cosa que diga tu crítico interno</li><li>Tu pareja te ayuda a replantearlo como Coach Interno</li><li>Escribe la nueva frase</li></ol><p><strong>Persona B (1,5 min):</strong></p><ol><li>El mismo proceso</li><li>Comparte tu pensamiento de Crítico Interno</li><li>Obtenga ayuda para replantearlo</li></ol><p>¿Listos? ¡Vamos!</p><p><em>Compartiremos algunos ejemplos con el grupo después...</em></p><hr><h2 id="diapositiva-11-herramienta-n-°-1-el-reinicio-de-3-respiraciones-🌬️" tabindex="-1">Diapositiva 11: Herramienta n.° 1: El reinicio de 3 respiraciones 🌬️ <a class="header-anchor" href="#diapositiva-11-herramienta-n-°-1-el-reinicio-de-3-respiraciones-🌬️" aria-label="Permalink to &quot;Diapositiva 11: Herramienta n.° 1: El reinicio de 3 respiraciones 🌬️&quot;">​</a></h2><h3 id="su-valvula-de-liberacion-de-presion-de-emergencia" tabindex="-1">Su válvula de liberación de presión de emergencia <a class="header-anchor" href="#su-valvula-de-liberacion-de-presion-de-emergencia" aria-label="Permalink to &quot;Su válvula de liberación de presión de emergencia&quot;">​</a></h3><p><strong>Utilice esto cuando:</strong></p><ul><li>😤 Acabas de cometer un error</li><li>😰 Sientes que la presión va en aumento</li><li>🤯Tu mente está acelerada</li></ul><h3 id="el-proceso-1" tabindex="-1">El proceso: <a class="header-anchor" href="#el-proceso-1" aria-label="Permalink to &quot;El proceso:&quot;">​</a></h3><p><strong>🌬️ RESPIRACIÓN 1 (Inhalar 4 segundos):</strong> Observa dónde sientes tensión (¿hombros? ¿mandíbula? ¿estómago?)</p><p><strong>🌬️ RESPIRACIÓN 2 (Exhala 6 segundos):</strong> Libera esa tensión. Deja que fluya con tu respiración.</p><p><strong>🌬️ RESPIRACIÓN 3 (Inhalar 4, Exhalar 6):</strong> Vuelve a centrarte en el AHORA. En esta toma. En este momento. En nada más.</p><p><strong>⏱️ Toma 20 segundos. Lo cambia todo.</strong></p><hr><h2 id="diapositiva-12-demo-¡pruebenlo-todos-🌬️" tabindex="-1">Diapositiva 12: DEMO - ¡Pruébenlo todos! 🌬️ <a class="header-anchor" href="#diapositiva-12-demo-¡pruebenlo-todos-🌬️" aria-label="Permalink to &quot;Diapositiva 12: DEMO - ¡Pruébenlo todos! 🌬️&quot;">​</a></h2><h3 id="practica-de-reinicio-de-3-respiraciones-1-minuto" tabindex="-1">Práctica de reinicio de 3 respiraciones (1 minuto) <a class="header-anchor" href="#practica-de-reinicio-de-3-respiraciones-1-minuto" aria-label="Permalink to &quot;Práctica de reinicio de 3 respiraciones (1 minuto)&quot;">​</a></h3><p><strong>Todos cierren los ojos...</strong></p><p><strong>Respiración 1:</strong><em>Inhala durante 4...¿Dónde sientes tensión?</em></p><p><strong>Respiración 2:</strong><em>Exhala durante 6...Déjalo ir...</em></p><p><strong>Respiración 3:</strong><em>Entran 4, salen 6... Solo en el momento presente...</em></p><p>Abre los ojos. ¿Cómo te sientes?</p><p><em>Este es tu botón de reinicio. ¡Úsalo!</em></p><hr><h2 id="diapositiva-13-herramienta-n-°-2-tu-rutina-previa-al-disparo-🎯" tabindex="-1">Diapositiva 13: Herramienta n.° 2: Tu rutina previa al disparo 🎯 <a class="header-anchor" href="#diapositiva-13-herramienta-n-°-2-tu-rutina-previa-al-disparo-🎯" aria-label="Permalink to &quot;Diapositiva 13: Herramienta n.° 2: Tu rutina previa al disparo 🎯&quot;">​</a></h2><h3 id="construir-consistencia-automatica" tabindex="-1">Construir consistencia automática <a class="header-anchor" href="#construir-consistencia-automatica" aria-label="Permalink to &quot;Construir consistencia automática&quot;">​</a></h3><p><strong>La rutina de 4 pasos:</strong></p><p><strong>1️⃣ VISUALIZA (3 segundos)</strong> Visualiza la toma perfecta en tu mente. Observa cómo aterriza exactamente donde quieres.</p><p><strong>2️⃣ RESPIRA (2 segundos)</strong> Una respiración profunda. Pasa del modo planificación al modo ejecución.</p><p><strong>3️⃣ ANCLA (2 segundos)</strong> Toca tu bola. Siente el peso. Conexión física.</p><p><strong>4️⃣ EJECUTAR (2 segundos)</strong> Confía plenamente. Deja que tu cuerpo haga lo que sabe.</p><p><strong>⏱️ Total: 9 segundos. Siempre lo mismo.</strong></p><h3 id="por-que-funciona" tabindex="-1">Por qué funciona: <a class="header-anchor" href="#por-que-funciona" aria-label="Permalink to &quot;Por qué funciona:&quot;">​</a></h3><p><strong>Consistencia = Confianza = Rendimiento</strong></p><hr><h2 id="diapositiva-14-herramienta-n-°-3-protocolo-de-recuperacion-de-errores-🔄" tabindex="-1">Diapositiva 14: Herramienta n.° 3: Protocolo de recuperación de errores 🔄 <a class="header-anchor" href="#diapositiva-14-herramienta-n-°-3-protocolo-de-recuperacion-de-errores-🔄" aria-label="Permalink to &quot;Diapositiva 14: Herramienta n.° 3: Protocolo de recuperación de errores 🔄&quot;">​</a></h2><h3 id="¿mal-tiro-aqui-tienes-tu-recuperacion-en-4-pasos" tabindex="-1">¿Mal tiro? Aquí tienes tu recuperación en 4 pasos: <a class="header-anchor" href="#¿mal-tiro-aqui-tienes-tu-recuperacion-en-4-pasos" aria-label="Permalink to &quot;¿Mal tiro? Aquí tienes tu recuperación en 4 pasos:&quot;">​</a></h3><p><strong>1️⃣ RECONOCER (2 segundos)</strong> &quot;Eso no salió como estaba previsto.&quot; (Sin juicio, solo hechos)</p><p><strong>2️⃣ LIBERACIÓN (3 segundos)</strong> Reinicio físico: Agitar las manos, girar los hombros y caminar 3 pasos.</p><p><strong>3️⃣ REENFOCAR (3 segundos)</strong> &quot;El siguiente disparo es una NUEVA oportunidad.&quot; (No está relacionado con el anterior)</p><p><strong>4️⃣ EJECUTA (Usa tu rutina)</strong> Confía en tu rutina previa a la inyección. Un nuevo comienzo.</p><h3 id="la-idea-clave" tabindex="-1">La idea clave: <a class="header-anchor" href="#la-idea-clave" aria-label="Permalink to &quot;La idea clave:&quot;">​</a></h3><p><strong>Cada disparo es independiente. No cometas errores.</strong></p><p><em>Los mejores jugadores tienen la memoria más corta para los malos tiros.</em></p><hr><h2 id="diapositiva-15-hablando-en-serio-¿que-te-detiene-💬" tabindex="-1">Diapositiva 15: HABLANDO EN SERIO: ¿Qué te detiene? 💬 <a class="header-anchor" href="#diapositiva-15-hablando-en-serio-¿que-te-detiene-💬" aria-label="Permalink to &quot;Diapositiva 15: HABLANDO EN SERIO: ¿Qué te detiene? 💬&quot;">​</a></h2><h3 id="discusion-en-grupo-5-minutos" tabindex="-1">Discusión en grupo (5 minutos) <a class="header-anchor" href="#discusion-en-grupo-5-minutos" aria-label="Permalink to &quot;Discusión en grupo (5 minutos)&quot;">​</a></h3><p><strong>Cuéntanos tu opinión:</strong></p><p><strong>Pregunta 1:</strong> ¿Cuándo te sientes MÁS fluido? ¿Qué condiciones te ayudan?</p><p><strong>Pregunta 2:</strong> “¿Cuál es tu mayor desafío mental en la competición?”</p><p><strong>Pregunta 3:</strong><em>&quot;¿Cuál de estas herramientas te resuena más?&quot;</em></p><ul><li>Reinicio de 3 respiraciones</li><li>Rutina previa al disparo</li><li>Reformulación del entrenador interior</li><li>Recuperación de errores</li></ul><p><strong>Comparte abiertamente: ¡este es un espacio seguro!</strong></p><hr><h2 id="diapositiva-16-tu-plan-de-accion-¡elige-uno-✅" tabindex="-1">Diapositiva 16: Tu plan de acción: ¡Elige UNO! ✅ <a class="header-anchor" href="#diapositiva-16-tu-plan-de-accion-¡elige-uno-✅" aria-label="Permalink to &quot;Diapositiva 16: Tu plan de acción: ¡Elige UNO! ✅&quot;">​</a></h2><h3 id="el-desafio-de-esta-semana" tabindex="-1">El desafío de esta semana: <a class="header-anchor" href="#el-desafio-de-esta-semana" aria-label="Permalink to &quot;El desafío de esta semana:&quot;">​</a></h3><p><strong>Elige SÓLO UNA técnica para practicar:</strong></p><p><strong>Opción A: 🌬️ Reinicio de 3 respiraciones</strong> Úselo después de CADA error en el entrenamiento.</p><p><strong>Opción B: 🎯 Rutina previa a la inyección</strong> La misma rutina de 4 pasos en CADA lanzamiento</p><p><strong>Opción C: 💬 Coach Interior</strong> Reformular UN pensamiento crítico por sesión</p><p><strong>Opción D: 🔄 Cambio de modo</strong> Planificación de la práctica → cambio de ejecución</p><h3 id="¿por-que-solo-uno" tabindex="-1">¿Por qué sólo uno? <a class="header-anchor" href="#¿por-que-solo-uno" aria-label="Permalink to &quot;¿Por qué sólo uno?&quot;">​</a></h3><p><strong>Domina una herramienta antes de agregar otra.</strong><em>En el entrenamiento mental, la profundidad supera a la amplitud.</em></p><hr><h2 id="diapositiva-17-sigue-tu-progreso-📊" tabindex="-1">Diapositiva 17: Sigue tu progreso 📊 <a class="header-anchor" href="#diapositiva-17-sigue-tu-progreso-📊" aria-label="Permalink to &quot;Diapositiva 17: Sigue tu progreso 📊&quot;">​</a></h2><h3 id="que-tener-en-cuenta-esta-semana" tabindex="-1">Qué tener en cuenta esta semana: <a class="header-anchor" href="#que-tener-en-cuenta-esta-semana" aria-label="Permalink to &quot;Qué tener en cuenta esta semana:&quot;">​</a></h3><p><strong>🎯Momentos de flujo:</strong></p><ul><li>¿Cuándo te sentiste &quot;en la zona&quot;?</li><li>¿A qué hora del día?</li><li>¿Qué tipo de disparo?</li><li>¿Qué te ayudó a llegar ahí?</li></ul><p><strong>💪Éxito técnico:</strong></p><ul><li>¿Qué herramienta funcionó mejor?</li><li>¿Cuando lo usaste?</li><li>¿Cual fue el resultado?</li></ul><p><strong>📝Mantenga un registro simple:</strong><em>&quot;Utilicé el reinicio de 3 respiraciones después de un error → me sentí más tranquilo → tomé la siguiente inyección&quot;</em></p><h3 id="el-objetivo" tabindex="-1">El objetivo: <a class="header-anchor" href="#el-objetivo" aria-label="Permalink to &quot;El objetivo:&quot;">​</a></h3><p><strong>Encuentra TUS patrones. Construye TU sistema.</strong></p><hr><h2 id="diapositiva-18-continua-tu-viaje-🚀" tabindex="-1">Diapositiva 18: Continúa tu viaje 🚀 <a class="header-anchor" href="#diapositiva-18-continua-tu-viaje-🚀" aria-label="Permalink to &quot;Diapositiva 18: Continúa tu viaje 🚀&quot;">​</a></h2><h3 id="recursos-gratuitos-en-carreau-app" tabindex="-1">Recursos gratuitos en carreau.app: <a class="header-anchor" href="#recursos-gratuitos-en-carreau-app" aria-label="Permalink to &quot;Recursos gratuitos en carreau.app:&quot;">​</a></h3><p><strong>📚 Inmersiones profundas:</strong></p><ul><li><strong>La Zona</strong> - Domina los estados de flujo</li><li><strong>Fuerza mental</strong> - Gestión avanzada de la presión</li><li><strong>Dinámica de equipo</strong> - Comunicación y confianza</li><li><strong>Mindfulness</strong> - Enfoque en el momento presente</li></ul><p><strong>🛠️ Herramientas prácticas:</strong></p><ul><li><strong>Plantilla de objetivos</strong> - Estructura tu desarrollo</li><li><strong>Plantilla de diario</strong>: Realice un seguimiento del progreso diario</li><li><strong>Guía del taller</strong> - Organiza tus propias sesiones</li></ul><p><strong>Todo gratis. Todo accesible. Todo diseñado para jugadores de élite.</strong></p><hr><h2 id="diapositiva-19-las-4-grandes-ideas-💡" tabindex="-1">Diapositiva 19: Las 4 grandes ideas 💡 <a class="header-anchor" href="#diapositiva-19-las-4-grandes-ideas-💡" aria-label="Permalink to &quot;Diapositiva 19: Las 4 grandes ideas 💡&quot;">​</a></h2><h3 id="llevate-esto-a-casa" tabindex="-1">Llévate esto a casa: <a class="header-anchor" href="#llevate-esto-a-casa" aria-label="Permalink to &quot;Llévate esto a casa:&quot;">​</a></h3><p><strong>1️⃣ El flujo es una HABILIDAD, no suerte</strong> Puedes aprender a acceder a él a demanda</p><p><strong>2️⃣ Tu voz interior DA FORMA a tu desempeño</strong> Entrenate a ti mismo, no te critiques</p><p><strong>3️⃣ Herramientas sencillas que FUNCIONAN bajo presión</strong> Tres respiraciones. Una rutina. Un reinicio. Eso es todo.</p><p><strong>4️⃣ La práctica hace la PERMANENCIA</strong> Las habilidades mentales necesitan entrenamiento como las habilidades técnicas.</p><h3 id="la-verdad-1" tabindex="-1">La verdad: <a class="header-anchor" href="#la-verdad-1" aria-label="Permalink to &quot;La verdad:&quot;">​</a></h3><p><strong>El entrenamiento mental no es místico. Es práctico.</strong></p><hr><h2 id="diapositiva-20-¿preguntas-¡hablemos-💬" tabindex="-1">Diapositiva 20: ¿Preguntas? ¡Hablemos! 💬 <a class="header-anchor" href="#diapositiva-20-¿preguntas-¡hablemos-💬" aria-label="Permalink to &quot;Diapositiva 20: ¿Preguntas? ¡Hablemos! 💬&quot;">​</a></h2><h1 id="discusion-abierta" tabindex="-1">Discusión abierta <a class="header-anchor" href="#discusion-abierta" aria-label="Permalink to &quot;Discusión abierta&quot;">​</a></h1><p><strong>¿Qué preguntas tienes?</strong></p><p><strong>¿Qué experiencias quieres compartir?</strong></p><p><strong>¿Qué desafíos estás enfrentando?</strong></p><p><strong>¿Qué probarás primero?</strong></p><p><em>Esta es TU sesión. Hagámosla valiosa para TI.</em></p><hr><h2 id="diapositiva-21-tu-desafio-🎯" tabindex="-1">Diapositiva 21: Tu desafío 🎯 <a class="header-anchor" href="#diapositiva-21-tu-desafio-🎯" aria-label="Permalink to &quot;Diapositiva 21: Tu desafío 🎯&quot;">​</a></h2><h1 id="mision-de-esta-semana" tabindex="-1">Misión de esta semana: <a class="header-anchor" href="#mision-de-esta-semana" aria-label="Permalink to &quot;Misión de esta semana:&quot;">​</a></h1><p><strong>1️⃣ Elige UNA herramienta</strong> (Reinicio de 3 respiraciones, rutina previa a la toma, entrenador interno o cambio de modo)</p><p><strong>2️⃣ Practícalo CADA sesión</strong> (La consistencia supera a la intensidad)</p><p><strong>3️⃣ Observa qué cambios</strong> (Sigue tu progreso)</p><p><strong>4️⃣ Comparte tus resultados</strong> (Con tus compañeros de entrenamiento o en carreau.app)</p><h3 id="recordar" tabindex="-1">Recordar: <a class="header-anchor" href="#recordar" aria-label="Permalink to &quot;Recordar:&quot;">​</a></h3><p><strong>Pequeños cambios → Grandes resultados</strong></p><hr><h2 id="diapositiva-22-¡gracias-🙏" tabindex="-1">Diapositiva 22: ¡Gracias! 🙏 <a class="header-anchor" href="#diapositiva-22-¡gracias-🙏" aria-label="Permalink to &quot;Diapositiva 22: ¡Gracias! 🙏&quot;">​</a></h2><h1 id="¡lo-puedes-lograr" tabindex="-1">¡Lo puedes lograr! <a class="header-anchor" href="#¡lo-puedes-lograr" aria-label="Permalink to &quot;¡Lo puedes lograr!&quot;">​</a></h1><p><strong>Lo que aprendiste hoy:</strong></p><ul><li>✅ Cómo acceder a los estados de flujo</li><li>✅ Cómo gestionar a tu crítico interno</li><li>✅ Herramientas prácticas que funcionan bajo presión</li><li>✅ Un plan de acción claro para esta semana</li></ul><p><strong>Próximos pasos:</strong></p><ol><li>Elige tu técnica ÚNICA</li><li>Practiquelo consistentemente</li><li>Visita carreau.app para obtener más recursos</li><li>Comparte tu progreso con el grupo</li></ol><h3 id="el-viaje-comienza-ahora" tabindex="-1">El viaje comienza ahora: <a class="header-anchor" href="#el-viaje-comienza-ahora" aria-label="Permalink to &quot;El viaje comienza ahora:&quot;">​</a></h3><p><strong>El entrenamiento mental es práctico, no místico.</strong><strong>Empieza hoy. Verás resultados pronto.</strong></p><hr><p><em>Academia de Petanca - Desarrollo de jugadores de élite</em><em>carreau.app - Recursos gratuitos para jugadores de élite</em></p>',201)])])}]]);export{t as __pageData,r as default};
